node_classes.ocelot_proto:
'''Pure protocol helpers for the Applied Digital CPU-XA / Ocelot serial protocol.

Source: Applied Digital, CPU-XA Protocol document (3 March 2000), published at
http://www.appdig.com/Serprot/serprot.html. Nothing here touches the hub.

Not documented in that source, so deliberately not asserted here: the serial
settings (baud/parity) and the CRC algorithm on the 42-type responses (the CRC
bytes are read and ignored). The Get Variables frame is also not in that document:
it was supplied by the installer and checked on a real Ocelot (see FRAME_GET_VARIABLES).

I/O is read two ways: Get Latched I/O (command 50, used for SECU-16 and SECU-16I) and Get Real Time
I/O (a 42-type frame, used for RLY08-XA). See io_source_for_unit().
'''
import re
import threading
import time

LOCK = threading.RLock()
READ_DEADLINE = 2.0

ACK = (6, 0, 6)

TYPE_SECU16 = 11
TYPE_SECU16I = 12
TYPE_RLY08XA = 13
# Observed on a real Ocelot with one SECU-16IR installed (the protocol text does
# not list type codes): that module reported type code 6.
TYPE_SECU16IR = 6
# Observed, not documented: a real Ocelot reported 254 for every unit slot
# beyond its installed modules. It is treated as "nothing installed here".
TYPE_EMPTY_SLOT = 254

# Which read supplies a module's I/O data.
SOURCE_LATCHED = 'latched'
SOURCE_REALTIME = 'realtime'

CMD_GET_LATCHED_IO = 50
CMD_WRITE_VARIABLE = 41
CMD_SEND_RESIDENT_IR = 90
CMD_SEND_REMOTE_IR = 92
ZONE_ALL = 255
IR_ZONES = 16
# Highest IR number accepted for SECU-16IR zones, as stated by the installer. The
# protocol itself carries a 16-bit number.
IR_NUMBER_MAX = 1023
# Highest resident IR number, per the protocol document ("IRnumber (0 to 39)").
RESIDENT_IR_MAX = 39
# Write CPUXA Variable Data: data is a 16-bit value, LSB first. The variable number
# range 0-127 is as stated by the installer (versions up to 1.8.1 used 0-63, which is
# what the March 2000 protocol document lists: 0-60 regular, 61 Leopard beep counter,
# 62 time conversion, 63 Leopard screen number). Whether 61-63 are still special on
# hardware with 128 variables is not documented. The document does not say whether the
# value is signed; it is sent as unsigned.
VARIABLE_MAX = 127
VARIABLE_COUNT = VARIABLE_MAX + 1
VARIABLE_VALUE_MAX = 65535

# Settings added after 1.0: older installs do not have them in their saved config.
SEED_PARAM_KEYS = ('IPAddress', 'IPPort')
# Settings that no longer exist: Port (removed 1.6.0), X10Devices (removed 1.7.0 with X-10 support),
# Baud (removed 1.8.0).
OBSOLETE_PARAM_KEYS = ('Port', 'X10Devices', 'Baud')
# Of those, the ones whose value is superseded once IPAddress is set.
SUPERSEDED_BY_IP = ('Port',)
# Of those, the ones whose value never had any effect, so any value may be deleted.
IGNORED_VALUE_KEYS = ('Baud',)

# Fixed read frames. FRAME_GET_LATCHED_IO, FRAME_GET_REALTIME_IO and FRAME_GET_UNIT_TYPE are
# exactly as published in the protocol document.
# Get Latched I/O: a 200-type frame (command 50, checksum 250). Reply: 3-byte header 6,0,6, then
# 256 data bytes (no 6-byte header and no CRC, unlike the 42-type reads). Not yet checked on hardware.
FRAME_GET_LATCHED_IO = bytes([200, 50, 0, 0, 0, 0, 0, 250])
FRAME_GET_REALTIME_IO = bytes([42, 0, 0, 141, 181, 0, 37, 233])
FRAME_GET_UNIT_TYPE = bytes([42, 0, 0, 1, 176, 0, 148, 39])
# Get Variables: NOT in the protocol document. Supplied by the installer and tested on a real
# Ocelot, which answered with 264 bytes: a 6-byte header equal to the first six bytes of this
# request (2a 00 00 91 aa 00), 256 data bytes and 2 trailer bytes (CRC, not interpreted).
# The last two request bytes cannot be computed here, so the frame is sent as given.
# The data is 128 variables of 16 bits each, LSB first: variable n is data[2n] | data[2n+1] << 8
# (confirmed on that Ocelot: variable 58 = 999 and variable 59 = 1001 were at data bytes 116-119
# as e7 03 e9 03).
FRAME_GET_VARIABLES = bytes([42, 0, 0, 145, 170, 0, 0, 166])
GET_VARIABLES_HEADER = tuple(FRAME_GET_VARIABLES[:6])

_HOST_LABEL = re.compile(r'^[A-Za-z0-9]([A-Za-z0-9-]{0,61}[A-Za-z0-9])?$')
_PORT_NUMBER = re.compile(r'^[0-9]{1,5}$')


def valid_host(host):
    '''True for a dotted-quad IPv4 address or a plain DNS host name (IPv6 is not supported).'''
    if not host or len(host) > 253:
        return False
    if re.match(r'^[0-9.]+$', host):
        parts = host.split('.')
        return len(parts) == 4 and all(p.isdigit() and len(p) <= 3 and 0 <= int(p) <= 255 for p in parts)
    return all(_HOST_LABEL.match(label) for label in host.split('.'))


def resolve_port(params):
    '''Work out what to open from the saved settings. Returns (port, error); exactly one is None.

    Only IPAddress + IPPort are used, giving socket://IPAddress:IPPort. The removed Port setting is
    ignored when IPAddress is set; if it is the only thing configured, the error says it is gone.
    '''
    params = params or {}

    def get(key):
        return str(params.get(key, '') or '').strip()

    ip, ipport, legacy = get('IPAddress'), get('IPPort'), get('Port')
    if ip:
        if not valid_host(ip):
            return None, ('IPAddress "%s" is not a valid IPv4 address or host name. Enter just the address, '
                          'for example 192.168.0.70 (no socket:// prefix and no :port).' % ip)
        if not ipport:
            return None, 'IPAddress is set but IPPort is empty. Enter the TCP port of the serial-to-Ethernet adapter, for example 3001.'
        if not _PORT_NUMBER.match(ipport) or not 1 <= int(ipport) <= 65535:
            return None, 'IPPort must be a whole number from 1 to 65535, not "%s".' % ipport
        return 'socket://%s:%d' % (ip, int(ipport)), None
    if ipport:
        return None, 'IPPort is set but IPAddress is empty. Enter the IP address or host name of the serial-to-Ethernet adapter.'
    if legacy:
        return None, ('The Port setting was removed in version 1.6.0. Enter the serial-to-Ethernet adapter\'s '
                      'IPAddress and IPPort instead (the old Port value was "%s").' % legacy)
    return None, 'Set IPAddress and IPPort (the serial-to-Ethernet adapter) in the plugin configuration.'


def missing_param_keys(params):
    '''Keys from SEED_PARAM_KEYS absent from a non-empty saved config (so they can be added empty).

    An empty config is left alone: there is nothing of the user's to preserve and PG3 seeds its own defaults.
    '''
    if not params:
        return []
    return [k for k in SEED_PARAM_KEYS if k not in params]


def obsolete_param_keys(params):
    '''Removed settings still in the saved config that are safe to delete.

    An empty entry is always safe. A Port that holds a value is also safe once IPAddress is set (the
    value is superseded), and Baud is safe with any value. Anything else that still holds a value is
    kept so it is never silently lost: a Port with no IPAddress (resolve_port() explains what to do)
    and any X10Devices list (there is no replacement for X-10 support; discover() shows a notice).
    '''
    params = params or {}
    ip = str(params.get('IPAddress', '') or '').strip()
    out = []
    for key in OBSOLETE_PARAM_KEYS:
        if key not in params:
            continue
        empty = not str(params.get(key, '') or '').strip()
        superseded = bool(ip) and key in SUPERSEDED_BY_IP
        if empty or superseded or key in IGNORED_VALUE_KEYS:
            out.append(key)
    return out


def checksum(values):
    return sum(values) & 0xFF


def build_frame(cmd, p1=0, p2=0, p3=0, p4=0, p5=0):
    body = [200, cmd, p1, p2, p3, p4, p5]
    return bytes(body + [checksum(body)])


def open_port(port, timeout=1.0):
    import serial
    # pyserial's API needs a baud value; for socket:// it is ignored (the adapter sets the real one)
    return serial.serial_for_url(port, baudrate=9600, bytesize=8, parity='N', stopbits=1, timeout=timeout)


def read_exact(ser, n):
    buf = bytearray()
    end = time.monotonic() + READ_DEADLINE
    while len(buf) < n and time.monotonic() < end:
        chunk = ser.read(n - len(buf))
        if chunk:
            buf.extend(chunk)
        else:
            time.sleep(0.01)
    return bytes(buf)


def _send(ser, frame):
    try:
        ser.reset_input_buffer()
    except Exception:
        pass
    ser.write(frame)
    try:
        ser.flush()
    except Exception:
        pass


def send_command(ser, frame):
    '''Send a frame and return True if the Ocelot answered with the 6,0,6 acknowledgement.'''
    with LOCK:
        _send(ser, frame)
        return tuple(read_exact(ser, 3)) == ACK


def read_block(ser, frame, header_len, trailer_len=0, expect_header=None):
    '''Send a frame and return the 256 data bytes of the reply, or None on a short/bad reply.'''
    with LOCK:
        _send(ser, frame)
        raw = read_exact(ser, header_len + 256 + trailer_len)
    if len(raw) < header_len + 256:
        return None
    if expect_header is not None and tuple(raw[:header_len]) != tuple(expect_header):
        return None
    return raw[header_len:header_len + 256]


def get_realtime_io(ser):
    return read_block(ser, FRAME_GET_REALTIME_IO, 6, 2)


def get_latched_io(ser):
    '''Send Get Latched I/O and return the 256 data bytes, or None on a short reply or a header other than 6,0,6.

    Reading the latched data clears the latches (stated by the installer; the document does not say).
    '''
    return read_block(ser, FRAME_GET_LATCHED_IO, 3, 0, expect_header=ACK)


def get_unit_types(ser):
    return read_block(ser, FRAME_GET_UNIT_TYPE, 6, 2)


def get_variables(ser):
    '''Send Get Variables and return the 256 data bytes, or None on a short reply or a wrong header.'''
    return read_block(ser, FRAME_GET_VARIABLES, 6, 2, expect_header=GET_VARIABLES_HEADER)


def parse_variables(data):
    '''Turn the 256 data bytes of a Get Variables reply into a list of 128 values (LSB first).

    Raises ValueError if fewer than 256 bytes are given.
    '''
    if data is None or len(data) < 2 * VARIABLE_COUNT:
        raise ValueError('Get Variables data must be %d bytes' % (2 * VARIABLE_COUNT))
    return [data[2 * n] | (data[2 * n + 1] << 8) for n in range(VARIABLE_COUNT)]


def parse_unit_types(data):
    '''Map unit number (1-based) -> type code for the first 128 bytes; zero means no unit.'''
    return {i + 1: data[i] for i in range(128) if data[i]}


def io_source_for_unit(unit_type):
    '''Which read supplies this unit type's I/O data, or None for a type without I/O points.

    SECU-16 and SECU-16I use Get Latched I/O (installer's choice, 1.13.0); RLY08-XA stays on Get Real
    Time I/O. The document describes an RLY08-XA latched layout with the relays in the second byte,
    which contradicts what was measured on a real RLY08-XA (first byte), so that unit is not moved.
    '''
    if unit_type in (TYPE_SECU16, TYPE_SECU16I):
        return SOURCE_LATCHED
    if unit_type == TYPE_RLY08XA:
        return SOURCE_REALTIME
    return None


def points_for_unit(unit_type):
    '''Return [(kind, index, byte, bit)] for a unit type; byte 0 is Data1, byte 1 is Data2.

    Layouts (the same positions in the latched and the real-time reply for SECU-16 and SECU-16I):
      SECU-16   inputs in Data1, relays in Data2. Confirmed by the installer on real hardware
                (reported working, read with Get Real Time I/O). The protocol document gives the same
                layout for Get Latched I/O.
      SECU-16I  16 inputs, Data1 then Data2. Not confirmed on hardware (the document gives this layout).
      RLY08-XA  8 relays in Data1 (bit n = relay n), Data2 unused. Confirmed on a real unit by
                switching relay 7: bit 7 of Data1 followed it and Data2 stayed 0. Versions up to
                1.8.0 read Data2, so these relays always showed Off.
    '''
    pts = []
    if unit_type == TYPE_SECU16:
        pts += [('input', i, 0, i) for i in range(8)]
        pts += [('relay', i, 1, i) for i in range(8)]
    elif unit_type == TYPE_SECU16I:
        pts += [('input', i, 0 if i < 8 else 1, i % 8) for i in range(16)]
    elif unit_type == TYPE_RLY08XA:
        pts += [('relay', i, 0, i) for i in range(8)]
    return pts


def classify_units(types):
    '''Split {unit: type_code} into (supported, unsupported, empty).

    supported   -- {unit: type_code} for types this plugin builds nodes for
                   (I/O modules with points, and SECU-16IR IR modules)
    unsupported -- {unit: type_code} for any other code except the empty-slot marker; each one
                   gets a placeholder node (see placeholder_name())
    empty       -- sorted list of units reporting the empty-slot marker (254)
    '''
    supported, unsupported, empty = {}, {}, []
    for unit, utype in sorted(types.items()):
        if points_for_unit(utype) or utype == TYPE_SECU16IR:
            supported[unit] = utype
        elif utype == TYPE_EMPTY_SLOT:
            empty.append(unit)
        else:
            unsupported[unit] = utype
    return supported, unsupported, empty


def placeholder_name(unit, unit_type):
    '''Node name of the placeholder for an unsupported module: 'Mod <unit> Type <type code>'.'''
    return 'Mod %d Type %d' % (unit, unit_type)


def placeholder_address(unit, unit_type):
    '''Node address of that placeholder, 'u<unit>t<type code>' (at most 8 characters for units 1-128, types 0-255).

    The type is part of the address so the name and the address always agree: a unit that later
    reports a different type gets a new placeholder instead of a stale name.
    '''
    return 'u%dt%d' % (unit, unit_type)


def get_bit(data, unit, byte, bit):
    return (data[2 * (unit - 1) + byte] >> bit) & 1


def write_relay(ser, unit, relay, on):
    if not (0 < unit <= 128 and 0 <= relay <= 7):
        raise ValueError('unit must be 1-128 and relay 0-7')
    return send_command(ser, build_frame(51, unit, relay, 1 if on else 0))


def build_variable_write(vnum, value):
    '''Frame for Write CPUXA Variable Data: 200, 41, vnum, LSB, MSB, 0, 0, csum.'''
    if not 0 <= vnum <= VARIABLE_MAX:
        raise ValueError('variable number must be 0-%d' % VARIABLE_MAX)
    if not 0 <= value <= VARIABLE_VALUE_MAX:
        raise ValueError('variable value must be 0-%d' % VARIABLE_VALUE_MAX)
    return build_frame(CMD_WRITE_VARIABLE, vnum, value & 0xFF, value >> 8)


def write_variable(ser, vnum, value):
    return send_command(ser, build_variable_write(vnum, value))


def _named_params(command):
    '''Map upper-cased parameter names to values from a command dict.

    PG3 delivers named parameters in command['query'] with keys like 'VARNUM.uom107'.
    '''
    query = (command or {}).get('query') or {}
    found = {}
    for key, value in query.items():
        found[str(key).split('.')[0].upper()] = value
    return found


def parse_variable_command(command):
    '''Extract (vnum, value) from a Write Variable command dict. Raises ValueError if missing/invalid.'''
    found = _named_params(command)
    out = []
    for name, top in (('VARNUM', VARIABLE_MAX), ('VALUE', VARIABLE_VALUE_MAX)):
        if name not in found:
            raise ValueError('missing parameter %s' % name)
        try:
            n = int(float(found[name]))
        except (TypeError, ValueError):
            raise ValueError('%s is not a number: %r' % (name, found[name]))
        if not 0 <= n <= top:
            raise ValueError('%s must be 0-%d, got %d' % (name, top, n))
        out.append(n)
    return out[0], out[1]


def parse_variable_number(command):
    '''Extract the variable number (0-127) from a Read Variable command dict. Raises ValueError otherwise.'''
    found = _named_params(command)
    if 'VARNUM' not in found:
        raise ValueError('missing parameter VARNUM')
    try:
        n = int(float(found['VARNUM']))
    except (TypeError, ValueError):
        raise ValueError('VARNUM is not a number: %r' % (found['VARNUM'],))
    if not 0 <= n <= VARIABLE_MAX:
        raise ValueError('VARNUM must be 0-%d, got %d' % (VARIABLE_MAX, n))
    return n


def build_remote_ir(mnum, znum, irnum):
    '''Frame for Send Remote IR Command: 200, 92, mnum, znum, IRlo, IRhi, 0, csum.

    mnum is the SECU-16IR unit (1-128), znum the zone (0-15, or 255 for all
    zones), irnum the previously learned IR number as a 16-bit value.
    '''
    if not 1 <= mnum <= 128:
        raise ValueError('IR module unit must be 1-128')
    if not (0 <= znum <= 15 or znum == ZONE_ALL):
        raise ValueError('IR zone must be 0-15, or 255 for all zones')
    if not 0 <= irnum <= 65535:
        raise ValueError('IR number must be 0-65535')
    return build_frame(CMD_SEND_REMOTE_IR, mnum, znum, irnum & 0xFF, irnum >> 8)


def send_remote_ir(ser, mnum, znum, irnum):
    return send_command(ser, build_remote_ir(mnum, znum, irnum))


def build_resident_ir(irnum):
    '''Frame for Send Resident IR: 200, 90, LSB, MSB, 0, 0, 0, csum.

    The Ocelot sends the IR command stored under irnum (0-39 per the protocol
    document) through its own IR output.
    '''
    if not 0 <= irnum <= RESIDENT_IR_MAX:
        raise ValueError('resident IR number must be 0-%d' % RESIDENT_IR_MAX)
    return build_frame(CMD_SEND_RESIDENT_IR, irnum & 0xFF, irnum >> 8)


def send_resident_ir(ser, irnum):
    return send_command(ser, build_resident_ir(irnum))


def parse_ir_number(command, max_num=IR_NUMBER_MAX):
    '''Extract the IR number from a Send IR command dict (0-max_num). Raises ValueError otherwise.

    PG3 delivers named parameters in command['query'] with keys like 'IRNUM.uom108'.
    '''
    found = _named_params(command)
    if 'IRNUM' not in found:
        raise ValueError('missing parameter IRNUM')
    try:
        irnum = int(float(found['IRNUM']))
    except (TypeError, ValueError):
        raise ValueError('IRNUM is not a number: %r' % (found['IRNUM'],))
    if not 0 <= irnum <= max_num:
        raise ValueError('IR number must be 0-%d, got %d' % (max_num, irnum))
    return irnum


def rescan(ser):
    return send_command(ser, build_frame(32))

node_classes.ocelot_ctl:
'''Controller-side glue for the Ocelot plugin. Every function takes the Controller instance.'''
import os
import threading
import time
import udi_interface
import ocelot_proto as op
from ocelot_nodes import OcelotIRZone, OcelotResidentIR, OcelotVariables, OcelotPlaceholder, io_node_class

LOGGER = udi_interface.LOGGER
TRUE_WORDS = ('1', 'true', 'yes', 'on')
LEGACY_IR_MARKER = 'legacy_ir_node_cleaned'

# The order the I/O reads are made in on each poll, and their names for the log and notices.
SOURCE_ORDER = (op.SOURCE_LATCHED, op.SOURCE_REALTIME)
SOURCE_NAMES = {op.SOURCE_LATCHED: 'Get Latched I/O', op.SOURCE_REALTIME: 'Get Real Time I/O'}

# Delete Module Nodes waits at most this long (seconds) for PG3 to confirm the node adds still queued,
# checking every ADD_WAIT_STEP seconds. PG3 confirmed adds about 0.6 s apart in the 1.16.0 log.
ADD_WAIT_TIMEOUT = 120.0
ADD_WAIT_STEP = 0.25

# Guards ctrl.pending_adds and ctrl.delete_running (touched by the add-done event thread, the command
# thread and the delete thread).
_PENDING_LOCK = threading.Lock()


def _notice(ctrl, key, text=None):
    try:
        if text is None:
            ctrl.poly.Notices.delete(key)
        else:
            ctrl.poly.Notices[key] = text
    except Exception as ex:
        LOGGER.debug('notice %s: %s' % (key, ex))


def _close(ctrl):
    with op.LOCK:
        ser = getattr(ctrl, 'ser', None)
        ctrl.ser = None
        ctrl.ser_key = None
        if ser is not None:
            try:
                ser.close()
            except Exception:
                pass


def _remove_legacy_ir_nodes(ctrl, ir_units):
    '''Version 1.1.x made one 'u<unit>ir' node per SECU-16IR. Remove those once.'''
    pdir = getattr(ctrl, 'persist_dir', None)
    marker = os.path.join(pdir, LEGACY_IR_MARKER) if pdir else None
    if marker and os.path.exists(marker):
        return
    try:
        for unit in ir_units:
            addr = ctrl.poly.getValidAddress('u%dir' % unit)
            if ctrl.poly.getNodeNameFromDb(addr) is not None:
                LOGGER.info('Removing legacy IR module node %s (replaced by per-zone nodes)' % addr)
                ctrl.poly.delNode(addr)
        if marker:
            with open(marker, 'w') as fh:
                fh.write('done\n')
    except Exception as ex:
        LOGGER.warning('Legacy IR node cleanup failed (will retry next start): %s' % ex)


def _sync_params(ctrl, params):
    '''Keep the saved config in line with the current settings: add new empty ones, delete removed ones.

    PG3's Custom._save() sends the WHOLE customparams dict, so the current values are loaded into the
    store first; otherwise saving would wipe every other setting. Removed settings are only deleted
    when op.obsolete_param_keys() says it is safe.
    '''
    missing = op.missing_param_keys(params)
    obsolete = op.obsolete_param_keys(params)
    if not missing and not obsolete:
        return
    try:
        store = udi_interface.Custom(ctrl.poly, 'customparams')
        store.load(params)
        for key in missing:
            store[key] = ''
        for key in obsolete:
            store.delete(key)
        if missing:
            LOGGER.info('Added new empty settings to the configuration page: %s' % ', '.join(missing))
        if obsolete:
            LOGGER.info('Removed obsolete settings from the configuration page: %s' % ', '.join(obsolete))
    except Exception as ex:
        LOGGER.warning('Could not update the saved settings (add %s, remove %s): %s' % (missing, obsolete, ex))


def set_params(ctrl, params):
    ctrl.ocelot_params = {str(k): v for k, v in (params or {}).items()}
    _sync_params(ctrl, ctrl.ocelot_params)
    if getattr(ctrl, 'ocelot_started', False):
        discover(ctrl)


def _pending(ctrl):
    '''The set of module node addresses whose add PG3 has not confirmed yet (create it if missing).

    Call with _PENDING_LOCK held.
    '''
    pending = getattr(ctrl, 'pending_adds', None)
    if pending is None:
        pending = ctrl.pending_adds = set()
    return pending


def _add_node(ctrl, node):
    '''poly.addNode() for a module node, remembering the add as unconfirmed until PG3's add-node-done event.

    PG3 works through its queue of node adds slowly (about 0.6 s per node), so an add can still be
    pending long after this call returns. Delete Module Nodes waits for these (see delete_modules()).
    The address is recorded before the add is sent so a fast confirmation cannot be missed.
    '''
    with _PENDING_LOCK:
        _pending(ctrl).add(node.address)
    try:
        ctrl.poly.addNode(node)
    except Exception:
        with _PENDING_LOCK:
            _pending(ctrl).discard(node.address)
        raise


def add_done(ctrl, data):
    '''Handle PG3's add-node-done event: that node's add is confirmed. Anything unexpected is ignored.'''
    address = data.get('address') if isinstance(data, dict) else None
    if address is None:
        return
    with _PENDING_LOCK:
        _pending(ctrl).discard(address)


def _subscribe_add_done(ctrl):
    '''Listen for add-node-done events (once). If that fails, tracking is turned off so nothing waits for them.'''
    if getattr(ctrl, 'add_done_listener', None) is not None:
        return

    def listener(data, _ctrl=ctrl):
        add_done(_ctrl, data)

    try:
        ctrl.poly.subscribe(ctrl.poly.ADDNODEDONE, listener)
    except Exception as ex:
        ctrl.add_tracking = False
        LOGGER.warning('Could not listen for node-added confirmations (%s); Delete Module Nodes will not wait for pending adds' % ex)
        return
    ctrl.add_done_listener = listener
    ctrl.add_tracking = True


def start(ctrl):
    ctrl.ser = None
    ctrl.ser_key = None
    ctrl.io_nodes = {}
    ctrl.ir_nodes = {}
    ctrl.placeholder_nodes = {}
    ctrl.resident_ir = None
    ctrl.var_node = None
    ctrl.io_fail = 0
    ctrl.ocelot_ready = False
    ctrl.ocelot_started = True
    ctrl.pending_adds = set()
    ctrl.delete_running = False
    _subscribe_add_done(ctrl)
    discover(ctrl)


def stop(ctrl):
    ctrl.ocelot_ready = False
    ctrl.ocelot_started = False
    _close(ctrl)


def _sync_placeholders(ctrl, unsupported):
    '''Make one placeholder node per unsupported module ({unit: type code}); keep the set current.

    A placeholder for a module that has gone, or that now reports another type, is deleted; one that
    already exists is left alone, so repeated discovery never duplicates it. Placeholders have no
    commands and are never polled.
    '''
    held = getattr(ctrl, 'placeholder_nodes', None)
    if held is None:
        held = ctrl.placeholder_nodes = {}
    wanted = {}
    for unit, utype in sorted(unsupported.items()):
        wanted[ctrl.poly.getValidAddress(op.placeholder_address(unit, utype))] = (unit, utype)
    for addr in [a for a in held if a not in wanted]:
        LOGGER.info('Removing placeholder node %s (that module is gone or reports another type)' % addr)
        try:
            ctrl.poly.delNode(addr)
        except Exception as ex:
            LOGGER.warning('Could not remove placeholder node %s: %s' % (addr, ex))
        del held[addr]
    for addr, (unit, utype) in wanted.items():
        if addr in held:
            continue
        name = ctrl.poly.getValidName(op.placeholder_name(unit, utype))
        node = OcelotPlaceholder(ctrl.poly, ctrl.address, addr, name, unit, utype)
        _add_node(ctrl, node)
        held[addr] = node
        LOGGER.info('Created placeholder node "%s" for the unsupported module type %d at unit %d' % (name, utype, unit))


def discover(ctrl):
    params = getattr(ctrl, 'ocelot_params', None) or {}
    ctrl.ocelot_ready = False
    port, err = op.resolve_port(params)
    if err:
        _notice(ctrl, 'config', err)
        return
    _notice(ctrl, 'config')
    invert = str(params.get('InvertInputs', '') or '').strip().lower() in TRUE_WORDS
    if str(params.get('X10Devices', '') or '').strip():
        _notice(ctrl, 'x10', 'X-10 support was removed in version 1.7.0, so the X10Devices setting is ignored. Clear or delete it to dismiss this notice.')
    else:
        _notice(ctrl, 'x10')

    if ctrl.ser is not None and ctrl.ser_key != port:
        _close(ctrl)
    if ctrl.ser is None:
        LOGGER.info('Connecting to %s' % port)
        try:
            ctrl.ser = op.open_port(port)
            ctrl.ser_key = port
        except Exception as ex:
            LOGGER.error('Cannot open %s: %s' % (port, ex))
            _notice(ctrl, 'serial', 'Cannot open %s: %s' % (port, ex))
            return

    data = op.get_unit_types(ctrl.ser)
    if data is None:
        LOGGER.error('No answer to Get Unit Type on %s' % port)
        _notice(ctrl, 'serial', 'Opened %s but the Ocelot did not answer. Check the cable, the IPAddress/IPPort settings, and the serial settings on the adapter.' % port)
        return

    types = op.parse_unit_types(data)
    supported, unsupported, empty = op.classify_units(types)
    LOGGER.info('Ocelot units found (unit: type code): %s' % supported)
    if empty:
        LOGGER.debug('%d unit slots report the empty-slot marker (254); ignored' % len(empty))
    if unsupported:
        LOGGER.info('Unsupported module types found (unit: type code), placeholder nodes are made for them: %s' % unsupported)
    _notice(ctrl, 'units')
    _sync_placeholders(ctrl, unsupported)
    ir_units = [u for u, t in supported.items() if t == op.TYPE_SECU16IR]
    if ir_units:
        _remove_legacy_ir_nodes(ctrl, ir_units)
    for unit, utype in supported.items():
        if utype == op.TYPE_SECU16IR:
            for zone in range(op.IR_ZONES):
                addr = ctrl.poly.getValidAddress('u%dz%d' % (unit, zone))
                if addr in ctrl.ir_nodes:
                    continue
                name = ctrl.poly.getValidName('Mod %d IR Zone %d' % (unit, zone))
                node = OcelotIRZone(ctrl.poly, ctrl.address, addr, name, ctrl, unit, zone)
                _add_node(ctrl, node)
                ctrl.ir_nodes[addr] = node
            continue
        source = op.io_source_for_unit(utype)
        for kind, idx, byte, bit in op.points_for_unit(utype):
            tag = 'r' if kind == 'relay' else 'i'
            addr = ctrl.poly.getValidAddress('u%d%s%d' % (unit, tag, idx))
            node = ctrl.io_nodes.get(addr)
            if node is not None:
                if kind == 'input':
                    node.invert = invert
                continue
            name = ctrl.poly.getValidName('Mod %d %s %d' % (unit, kind.capitalize(), idx))
            # the node class sets the node type (profile nodedef) for this module kind, e.g. SECU16I Input
            node_class = io_node_class(utype, kind)
            if kind == 'relay':
                node = node_class(ctrl.poly, ctrl.address, addr, name, ctrl, unit, idx, byte, bit, source)
            else:
                node = node_class(ctrl.poly, ctrl.address, addr, name, unit, idx, byte, bit, invert, source)
            _add_node(ctrl, node)
            ctrl.io_nodes[addr] = node

    if getattr(ctrl, 'resident_ir', None) is None:
        addr = ctrl.poly.getValidAddress('residentir')
        node = OcelotResidentIR(ctrl.poly, ctrl.address, addr, ctrl.poly.getValidName('Ocelot Resident IR'), ctrl)
        ctrl.poly.addNode(node)
        ctrl.resident_ir = node

    if getattr(ctrl, 'var_node', None) is None:
        addr = ctrl.poly.getValidAddress('cpuxavars')
        node = OcelotVariables(ctrl.poly, ctrl.address, addr, ctrl.poly.getValidName('Ocelot Variables'), ctrl)
        ctrl.poly.addNode(node)
        ctrl.var_node = node

    ctrl.io_fail = 0
    ctrl.ocelot_ready = True
    _notice(ctrl, 'serial')
    poll(ctrl)
    _refresh_variables(ctrl)


def _refresh_variables(ctrl, quiet=False):
    '''Read the variable table (Discover, Query, and every short poll via short_poll()).

    quiet=True logs a successful read at debug level (used by the short poll).
    '''
    node = getattr(ctrl, 'var_node', None)
    if node is None or getattr(ctrl, 'ser', None) is None:
        return
    try:
        node.refresh(quiet=quiet)
    except Exception as ex:
        LOGGER.error('Variable refresh failed: %s' % ex)


def _read_source(ser, source):
    '''One I/O read: Get Latched I/O for the latched source, otherwise Get Real Time I/O.'''
    if source == op.SOURCE_LATCHED:
        return op.get_latched_io(ser)
    return op.get_realtime_io(ser)


def _node_source(node):
    return getattr(node, 'source', op.SOURCE_REALTIME)


def poll(ctrl, sources=None, skip=None):
    '''Read the I/O and update the relay and input nodes.

    By default (sources=None) only the reads that the installed nodes need are made: Get Latched I/O
    when there are SECU-16 or SECU-16I nodes, then Get Real Time I/O when there are RLY08-XA nodes.
    With no I/O nodes at all one Get Real Time I/O read is still made, as the check that the Ocelot
    answers. Each node is updated from the read that supplies it. If any read gets no answer the
    poll counts as failed (io_fail), but the nodes of a read that did answer are still updated.

    sources limits the poll to those sources (a tuple of op.SOURCE_* values), and only those that
    installed nodes actually use are read: OcelotRelay passes (op.SOURCE_LATCHED,) after a relay
    command, so no real-time read is made, and nothing at all is read when there are no latched nodes.

    skip is a tuple of nodes whose status is left as it is (the read is still made and still counts):
    OcelotRelay passes itself after an acknowledged command, because a latched relay bit read right
    after the command can still carry the old state and would undo the status just sent to IoX.
    '''
    if not getattr(ctrl, 'ocelot_ready', False) or getattr(ctrl, 'ser', None) is None:
        return
    nodes = list(ctrl.io_nodes.values())
    present = {_node_source(n) for n in nodes}
    if sources is None:
        chosen = [s for s in SOURCE_ORDER if s in present] or [op.SOURCE_REALTIME]
    else:
        chosen = [s for s in SOURCE_ORDER if s in present and s in sources]
        if not chosen:
            return
    skipped = {id(n) for n in (skip or ())}
    failed = []
    for source in chosen:
        try:
            data = _read_source(ctrl.ser, source)
        except Exception as ex:
            LOGGER.error('I/O poll (%s) failed: %s' % (SOURCE_NAMES[source], ex))
            data = None
        if data is None:
            failed.append(SOURCE_NAMES[source])
            continue
        for node in nodes:
            if _node_source(node) == source and id(node) not in skipped:
                node.update_from(data)
    if failed:
        if ctrl.io_fail == 0:
            LOGGER.warning('No valid answer to: %s' % ', '.join(failed))
        ctrl.io_fail += 1
        if ctrl.io_fail == 3:
            _notice(ctrl, 'serial', 'The Ocelot has stopped answering (no valid answer to: %s). Will keep retrying.' % ', '.join(failed))
        return
    if ctrl.io_fail >= 3:
        _notice(ctrl, 'serial')
    ctrl.io_fail = 0


def short_poll(ctrl):
    '''Every short poll: read the I/O (latched and/or real-time), then the 128 program variables.

    The variable read is skipped when any I/O read in this same cycle got no answer (the link is
    probably down; another read would only add another timeout) or the plugin is not ready.
    poll() itself is left as it was because discover() and query() call it and already read the
    variables themselves.
    '''
    if not getattr(ctrl, 'ocelot_ready', False) or getattr(ctrl, 'ser', None) is None:
        return
    poll(ctrl)
    if getattr(ctrl, 'io_fail', 0) != 0:
        return
    _refresh_variables(ctrl, quiet=True)


def long_poll(ctrl):
    if not getattr(ctrl, 'ocelot_started', False):
        return
    if (not getattr(ctrl, 'ocelot_ready', False)) or getattr(ctrl, 'io_fail', 0) >= 3:
        _close(ctrl)
        discover(ctrl)


def rescan(ctrl):
    ser = getattr(ctrl, 'ser', None)
    if ser is None:
        LOGGER.error('Rescan requested but the serial port is not open')
        return
    ok = op.rescan(ser)
    LOGGER.info('Rescan %s' % ('acknowledged' if ok else 'NOT acknowledged'))
    time.sleep(2)
    discover(ctrl)


def _wait_for_pending_adds(ctrl, timeout=None, step=None):
    '''Wait until PG3 has confirmed every module node add. Returns how many were still unconfirmed (0 = all done).

    Gives up after timeout seconds (default ADD_WAIT_TIMEOUT), checking every step seconds (default
    ADD_WAIT_STEP). Returns 0 at once when add tracking is off (the confirmation event could not be
    subscribed to), since nothing would ever clear the pending set.
    '''
    timeout = ADD_WAIT_TIMEOUT if timeout is None else timeout
    step = ADD_WAIT_STEP if step is None else step
    if getattr(ctrl, 'add_tracking', True) is False:
        return 0
    deadline = time.monotonic() + timeout
    announced = False
    while True:
        with _PENDING_LOCK:
            left = len(_pending(ctrl))
        if left == 0:
            return 0
        if time.monotonic() >= deadline:
            return left
        if not announced:
            LOGGER.info('Delete Module Nodes: waiting for PG3 to finish adding %d nodes before deleting' % left)
            announced = True
        time.sleep(step)


def _delete_module_nodes(ctrl):
    '''Delete every expansion-module node this run knows about: relays, inputs, SECU-16IR zones, placeholders.

    The Controller, the Ocelot Resident IR node and the Ocelot Variables node are kept: they belong to
    the Ocelot itself, not to an expansion module. Nothing is sent to the Ocelot.

    The registries are emptied first (in place, so every reference to them stays valid), so a poll running
    at the same moment no longer sees the nodes about to go; then each node is deleted. One node that
    cannot be deleted is logged and does not stop the others. Discover, Rescan Modules, a connection
    setting change and a plugin restart create the module nodes again, because they are found on the
    Ocelot. Only nodes this run created or re-discovered are known: a node left over from an earlier run
    (for example a placeholder whose module has gone) is not in the registries and stays.
    '''
    addresses = []
    for registry_name in ('io_nodes', 'ir_nodes', 'placeholder_nodes'):
        registry = getattr(ctrl, registry_name, None)
        if registry:
            addresses.extend(registry.keys())
            registry.clear()
    if not addresses:
        LOGGER.info('Delete Module Nodes: there are no expansion module nodes to delete')
        return
    with _PENDING_LOCK:
        _pending(ctrl).difference_update(addresses)
    removed, failed = 0, 0
    for addr in addresses:
        try:
            ctrl.poly.delNode(addr)
            removed += 1
        except Exception as ex:
            failed += 1
            LOGGER.warning('Delete Module Nodes: could not delete node %s: %s' % (addr, ex))
    LOGGER.info('Delete Module Nodes: deleted %d module nodes%s (the controller, Ocelot Resident IR and Ocelot Variables are kept)'
                % (removed, ', %d could not be deleted' % failed if failed else ''))


def _delete_worker(ctrl, wait=None):
    '''Body of the Delete Module Nodes thread: wait for PG3's pending adds, then delete (see delete_modules()).'''
    try:
        left = _wait_for_pending_adds(ctrl, wait)
        if left:
            LOGGER.warning('Delete Module Nodes: PG3 had still not confirmed %d node adds after waiting; deleting anyway. '
                           'Any of those nodes that PG3 adds afterwards will stay: press Rescan Modules, wait, then Delete Module Nodes again.' % left)
        _delete_module_nodes(ctrl)
    except Exception as ex:
        LOGGER.error('Delete Module Nodes failed: %s' % ex)
    finally:
        with _PENDING_LOCK:
            ctrl.delete_running = False


def delete_modules(ctrl, wait=None):
    '''The Delete Module Nodes command: delete the expansion-module nodes in a background thread.

    PG3 confirms node adds slowly (about 0.6 s each), and removing a node whose add is still queued does
    not stop that add: PG3 creates it afterwards (seen in the 1.16.0 log, 17 nodes re-created after the
    delete). So the thread first waits for PG3 to confirm the pending adds (up to wait seconds, default
    ADD_WAIT_TIMEOUT), then deletes. It is a thread so the command handler is not blocked: the
    confirmations are processed by the same handler. A second press while one is running is ignored.

    Returns the thread that was started, or None when one was already running.
    '''
    with _PENDING_LOCK:
        if getattr(ctrl, 'delete_running', False):
            already = True
        else:
            already = False
            ctrl.delete_running = True
    if already:
        LOGGER.info('Delete Module Nodes: already in progress, this request is ignored')
        return None
    thread = threading.Thread(target=_delete_worker, args=(ctrl, wait), name='ocelot-delete-modules', daemon=True)
    thread.start()
    return thread


def query(ctrl):
    poll(ctrl)
    _refresh_variables(ctrl)
    ctrl.reportDrivers()
    nodes = (list(getattr(ctrl, 'io_nodes', {}).values())
             + list(getattr(ctrl, 'ir_nodes', {}).values())
             + list(getattr(ctrl, 'placeholder_nodes', {}).values()))
    for extra in (getattr(ctrl, 'resident_ir', None), getattr(ctrl, 'var_node', None)):
        if extra is not None:
            nodes.append(extra)
    for n in nodes:
        n.reportDrivers()

